const crypto = require('crypto');
// CRITICAL FIX: HMAC must be computed over the exact raw body bytes Shopify
// sent, not JSON.stringify(parsedBody) — re-serializing can change key order,
// whitespace, and number formatting, silently breaking every signature check.
// With webhook option rawBody:true, the untouched body is available as a
// binary buffer on the item.
const rawBuffer = $input.item.binary?.data ? Buffer.from($input.item.binary.data.data, 'base64') : Buffer.from('');
const rawString = rawBuffer.toString('utf8');
const hmacHeader = $input.item.json.headers['x-shopify-hmac-sha256'] || '';
const digest = crypto.createHmac('sha256', $env.SHOPIFY_WEBHOOK_SECRET).update(rawBuffer).digest('base64');

// Timing-safe comparison — a plain === leaks timing information about how
// many leading bytes matched, which a plain string compare does not protect against.
function timingSafeEqual(a, b) {
  const bufA = Buffer.from(a); const bufB = Buffer.from(b);
  if (bufA.length !== bufB.length) return false;
  return crypto.timingSafeEqual(bufA, bufB);
}
const valid = hmacHeader.length > 0 && timingSafeEqual(hmacHeader, digest);

let parsed = {};
try { parsed = JSON.parse(rawString); } catch (e) {}
return { json: { valid, raw_body: rawString, parsed } };

const raw = $('Verify Shopify Signature').item.json.parsed;
const codNames = ($env.COD_GATEWAY_NAMES || 'cash_on_delivery,cod,manual').split(',').map(s => s.trim().toLowerCase());
const gateway = (raw.gateway || raw.payment_gateway_names?.[0] || '').toLowerCase();
const paymentMethod = codNames.some(n => gateway.includes(n)) ? 'cod' : 'online';
return { json: {
  checkout_token: raw.token || raw.id,
  customer_phone_raw: raw.customer?.phone || raw.phone || raw.shipping_address?.phone || null,
  customer_email: raw.email || raw.customer?.email || null,
  customer_name: raw.customer?.first_name || raw.billing_address?.first_name || null,
  shopify_customer_id: raw.customer?.id || null,
  // FIX (audit #1): capture the only real consent signal Shopify's checkout payload
  // carries. This is a MARKETING opt-in checkbox, not a WhatsApp-specific one —
  // see the delivery doc's honest caveat on this. If the business has a separate,
  // dedicated WhatsApp opt-in flow, that should write to customers.whatsapp_opt_in
  // directly instead of relying on this field alone.
  buyer_accepts_marketing: raw.buyer_accepts_marketing === true,
  payment_method: paymentMethod,
  cart_value: parseFloat(raw.total_price || '0'),
  currency: raw.currency || 'INR',
  line_items: raw.line_items || [],
  checkout_url: raw.abandoned_checkout_url || null
} };

const j = $json;
let phone = (j.customer_phone_raw || '').replace(/[^0-9+]/g, '');
if (phone && !phone.startsWith('+')) phone = '+91' + phone.replace(/^0+/, '');
const phoneValid = /^\+[1-9]\d{7,14}$/.test(phone);
const required_ok = !!j.checkout_token && j.cart_value > 0 && j.line_items.length > 0;
return { json: { ...j, customer_phone: phoneValid ? phone : null, phone_valid: phoneValid, valid: required_ok } };

// Real eligibility, not just phone-exists: a valid phone AND explicit
// opt-in AND no opt-out on file. Missing opt_in defaults to ineligible —
// never message on the strength of 'we have a number'.
const c = $json[0] || {};
let eligible = true, reason = null;
if (!c.phone_e164) { eligible = false; reason = 'no_phone'; }
else if (c.whatsapp_opt_out) { eligible = false; reason = 'opted_out'; }
else if (!c.whatsapp_opt_in) { eligible = false; reason = 'no_opt_in_on_file'; }
return { json: { eligible, reason } };

// PRODUCT REPRESENTATION CHOICE: with multiple line items, this uses the
// FIRST (primary) product's image and name, and appends '+ N more item(s)'
// to the body text rather than trying to render a multi-image carousel —
// WhatsApp template headers support exactly one media item, so a single
// deterministic 'primary product' representation is the only reliable choice
// that works inside an approved template.
const cart = $('Validate Required Fields').item.json;
const items = cart.line_items;
const primary = items[0];
const extraCount = items.length - 1;
const imageResult = $('Fetch Product Image (Primary Line Item)').item.json;
const imageUrl = imageResult?.images?.[0]?.src || null;
return { json: { ...cart, message_kind: 'first_touch_payment',
  product_name: primary.title + (extraCount > 0 ? ` (+${extraCount} more item${extraCount > 1 ? 's' : ''})` : ''),
  quantity: primary.quantity, price: primary.price, product_image_url: imageUrl,
  payment_link: $('Record Payment Attempt').item.json?.payment_link || null } };

const cart = $('Validate Required Fields').item.json;
const items = cart.line_items;
const primary = items[0];
const extraCount = items.length - 1;
return { json: { ...cart, message_kind: 'first_touch_cod',
  product_name: primary.title + (extraCount > 0 ? ` (+${extraCount} more item${extraCount > 1 ? 's' : ''})` : ''),
  quantity: primary.quantity, price: primary.price, product_image_url: null } };

const msg = $('Build COD Recovery Message').item.json;
const imageUrl = $json?.images?.[0]?.src || null;
return { json: { ...msg, product_image_url: imageUrl } };

const method = $('Validate Required Fields').item.json.payment_method;
const enabled = method === 'cod' ? ($env.COUPON_ENABLED_FOR_COD !== 'false') : ($env.COUPON_ENABLED_FOR_ONLINE !== 'false');
return { json: { enabled } };

const crypto = require('crypto');
const rawBuffer = $input.item.binary?.data ? Buffer.from($input.item.binary.data.data, 'base64') : Buffer.from('');
const rawString = rawBuffer.toString('utf8');
const sigHeader = $input.item.json.headers['x-razorpay-signature'] || '';
const digest = crypto.createHmac('sha256', $env.RAZORPAY_WEBHOOK_SECRET).update(rawBuffer).digest('hex');
function timingSafeEqual(a, b) {
  const bufA = Buffer.from(a); const bufB = Buffer.from(b);
  if (bufA.length !== bufB.length) return false;
  return crypto.timingSafeEqual(bufA, bufB);
}
const valid = sigHeader.length > 0 && timingSafeEqual(sigHeader, digest);
let parsed = {};
try { parsed = JSON.parse(rawString); } catch (e) {}
return { json: { valid, event: parsed.event, payload: parsed.payload } };
